from pathlib import Path

readme = Path("README.md")
s = readme.read_text(encoding="utf-8")
s = s.replace("当前稳定版本为 **v1.0.9**", "当前稳定版本为 **v1.0.10**")
s = s.replace("确认版本为 `1.0.9`", "确认版本为 `1.0.10`")
old = """## 🆕 v1.0.9 更新亮点

- 新增独立的原声音频提取与下载入口。
- 优化作者信息读取，并增加按需请求与短时缓存。
- 修复批量管理器选择状态与检查器不同步的问题。
- 修复管理器与悬浮胶囊互斥、任务封面和设置窗口裁切问题。
- 恢复一级下载记录入口，并新增任务状态悬浮信息。
- 新增作者作品一次性完整扫描与快速全选。
- 优化关于页信息层级、项目仓库与开源来源说明。"""
new = """## 🆕 v1.0.10 更新亮点

- 修复作者信息页粉丝数量可能显示旧值、占位值或不准确数据的问题。
- 强化作者 SecUID 归属校验，避免其他作者或无归属统计覆盖当前作者信息。
- 优化作者主页统计补取与 10 分钟短时缓存，减少重复请求。
- 增加作者主页已渲染粉丝数、获赞数的兼容兜底，提升网页结构调整后的可用性。
- 全面复核单视频、图集、原声音频、弹幕 ASS、作者主页扫描、批量任务、暂停恢复与媒体详情等关键代码路径。
- 保持低资源运行策略，不新增常驻轮询或持续动画。"""
if old not in s:
    raise SystemExit("README v1.0.9 release block not found")
s = s.replace(old, new, 1)
readme.write_text(s, encoding="utf-8")

gf = Path("GREASYFORK.md")
g = gf.read_text(encoding="utf-8")
g = g.replace("# 抖音下载 V1.0.9", "# 抖音下载 V1.0.10", 1)
oldg = """## V1.0.9 更新内容

- 增加作品原声音频提取与下载功能
- 优化作者粉丝数、获赞数等信息的补充读取
- 合并作品数据与作者资料，减少部分字段缺失
- 优化作者信息缓存，避免短时间内重复请求
- 改进暂停、恢复及下载任务状态处理
- 优化需求反馈与关于页面排版
- 保留并低调展示 MIT 开源许可与项目来源
- 修复若干已知问题并提升运行稳定性"""
newg = """## V1.0.10 更新内容

- 修复作者信息页粉丝数量可能显示旧值、占位值或不准确数据的问题
- 强化作者 SecUID 归属校验，降低不同来源统计数据误合并的风险
- 优化作者主页粉丝数、获赞数补充读取，并继续使用短时缓存减少重复请求
- 增加作者主页已渲染统计文本的兼容兜底，提高网页结构调整后的识别稳定性
- 复核视频、图集、原声音频、弹幕、作者主页扫描、批量任务、暂停恢复及媒体详情等关键功能路径
- 保持低资源运行策略，未增加常驻高频轮询"""
if oldg not in g:
    raise SystemExit("GREASYFORK v1.0.9 release block not found")
g = g.replace(oldg, newg, 1)
gf.write_text(g, encoding="utf-8")
